import {parseGraph,SpikingBrain} from './model.mjs';
import {FlyWorld} from './world.mjs';
let brain,manifest,graph,world=new FlyWorld(),paused=false,history=[],events=[],lastCounts,rateHistory=[],wallStart,simStart,lastPost=0,busy=false;
const send=(type,value)=>postMessage({type,...value});
async function load(){try{send('loading',{progress:0,message:'读取神经元清单…'});manifest=await (await fetch('data/manifest.json')).json();const res=await fetch('data/connectome.bin.gz');if(!res.ok)throw Error(`数据下载失败 (${res.status})`);const reader=res.body.getReader(),parts=[];let size=0;for(;;){const {value,done}=await reader.read();if(done)break;parts.push(value);size+=value.length;send('loading',{progress:Math.min(.9,size/manifest.gzipBytes*.9),message:`下载全脑连接 ${(size/1e6).toFixed(1)} / ${(manifest.gzipBytes/1e6).toFixed(1)} MB`});}
 send('loading',{progress:.93,message:'解压并校验连接表…'});const compressed=new Blob(parts);const buffer=await new Response(compressed.stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',buffer)),v=>v.toString(16).padStart(2,'0')).join('');if(hash!==manifest.binarySha256)throw Error('数据完整性校验失败，请重新加载');graph=parseGraph(buffer);brain=new SpikingBrain(graph,manifest.sugarIndices,manifest.mn9Index,42);lastCounts=new Uint32Array(graph.n);wallStart=performance.now();simStart=0;send('ready',{manifest});loop();
 }catch(e){send('error',{message:e.message});}}
function loop(){const start=performance.now();if(brain&&!paused&&!busy){const rate=world.sense();brain.silenceMotor=world.silenced;const r=brain.run(20,rate);rateHistory.push(r.mn9Spikes);if(rateHistory.length>10)rateHistory.shift();const hz=rateHistory.reduce((a,b)=>a+b,0)/(rateHistory.length*.02);world.step(.02,hz);const row={time:world.time,mn9Hz:hz,input:rate,spikes:r.spikes,active:r.active};history.push(row);if(history.length>6000)history.shift();
 if(start-lastPost>80){let strongest=[];for(let i=0;i<brain.n;i++){const count=brain.counts[i]-lastCounts[i];if(count)strongest.push({index:i,count});lastCounts[i]=brain.counts[i];}strongest.sort((a,b)=>b.count-a.count);send('state',{world:world.snapshot(),neural:{...row,total:brain.totalSpikes,neurons:brain.n,activeFraction:r.active/brain.n,activity:strongest.slice(0,100),mn9Voltage:brain.v[brain.motor]-52},performance:{ratio:(world.time-simStart)/((performance.now()-wallStart)/1000),stepMs:performance.now()-start},trace:history.slice(-100)});lastPost=start;}}
 setTimeout(loop,Math.max(0,20-(performance.now()-start)));}
onmessage=async({data:d})=>{if(d.type==='load'){load();return;}if(!brain)return;
 if(d.type==='pause'){paused=d.value;wallStart=performance.now();simStart=world.time;send('paused',{value:paused});}
 if(d.type==='food'){world.addFood(d.x,d.z);events.push({time:world.time,event:'food',x:d.x,z:d.z});}
 if(d.type==='pulse'){world.pulse();events.push({time:world.time,event:'sugar-pulse-150Hz'});}
 if(d.type==='blind'){world.blind=d.value;events.push({time:world.time,event:'sensory-cut',value:d.value});}
 if(d.type==='silence'){world.silenced=d.value;rateHistory=[];events.push({time:world.time,event:'MN9-silenced',value:d.value});}
 if(d.type==='reset'){brain.reset();world.reset();history=[];events=[];rateHistory=[];lastCounts.fill(0);wallStart=performance.now();simStart=0;send('reset',{});send('state',{world:world.snapshot(),neural:{active:0,total:0,activity:[]},performance:{ratio:0},trace:[]});}
 if(d.type==='export')send('export',{record:{dataset:manifest,seed:42,body:'engineered kinematic controller',integration:'0.1 ms linear point-neuron model; sparse tails truncated below 1e-9 mV',world:world.snapshot(),events,history}});
 if(d.type==='validate'&&!busy){busy=true;send('validationProgress',{message:'验证无输入 / 糖刺激 / MN9 沉默…'});const rows=[];try{for(const condition of ['baseline','sugar','silenced']){await new Promise(r=>setTimeout(r,10));const b=new SpikingBrain(graph,manifest.sugarIndices,manifest.mn9Index,42);b.silenceMotor=condition==='silenced';const t=performance.now();let count=0,total=0;for(let j=0;j<50;j++){const result=b.run(20,condition==='baseline'?0:100);count+=result.mn9Spikes;total+=result.spikes;if(j%10===0){send('validationProgress',{message:`${condition==='baseline'?'无输入':condition==='sugar'?'糖刺激':'MN9 沉默'} · ${j*2}%`});await new Promise(r=>setTimeout(r,0));}}rows.push({condition,mn9Hz:count,spikes:total,wallMs:Math.round(performance.now()-t)});}send('validation',{rows});}catch(e){send('error',{message:e.message});}finally{busy=false;wallStart=performance.now();simStart=world.time;}}
};